#!/bin/sh
# ============================================================
# abyss + USB启动顺序 补丁应用脚本
# 用法: 在 rt-n56u 源码根目录(包含 trunk/ 的目录)下执行:
#   sh apply_abyss_patch.sh
# ============================================================

set -e

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
ROOT="$SCRIPT_DIR"

if [ -d "$ROOT/trunk/user/rc" ]; then
    :
elif [ -d "$ROOT/user/rc" ]; then
    ROOT="$(dirname "$ROOT")"
else
    echo "[ERROR] 找不到源码目录, 请在 rt-n56u 源码根目录下执行"
    exit 1
fi

echo "[INFO] 源码根目录: $ROOT"
cd "$ROOT"

# ============================================================
# 步骤 1: 给 rc 源码打补丁 (6个文件)
# ============================================================
echo "[STEP 1/3] 应用 rc 源码补丁..."

cat > /tmp/abyss_rc.patch << 'PATCH_EOF'
diff --git a/trunk/user/rc/net_lan.c b/trunk/user/rc/net_lan.c
index c278c6e86..b67eb404b 100644
--- a/trunk/user/rc/net_lan.c
+++ b/trunk/user/rc/net_lan.c
@@ -815,6 +815,9 @@ lan_up_manual(char *lan_ifname, char *lan_dname)
 
 	/* fill XXX_t fields */
 	update_lan_status(0);
+
+	/* AP 静态 IP 模式下网络就绪后启动 abyss */
+	start_abyss();
 }
 
 static void
@@ -933,6 +936,10 @@ udhcpc_lan_deconfig(char *lan_ifname)
 
 	lan_down_auto(lan_ifname);
 
+	/* AP 模式下 LAN 断开时停止 abyss */
+	if (get_ap_mode())
+		stop_abyss();
+
 	logmessage("DHCP LAN Client", "%s: lease is lost", udhcpc_lan_state);
 
 	return 0;
@@ -1001,6 +1008,10 @@ udhcpc_lan_bound(char *lan_ifname, int is_renew)
 			udhcpc_lan_state, lan_ipaddr, lan_ipmask, lan_gateway, lease_dur);
 	}
 
+	/* AP 模式下 LAN 获得 IP 后启动 abyss (相当于路由模式的 WAN up) */
+	if (get_ap_mode())
+		start_abyss();
+
 	if (!is_renew)
 		restart_networkmap();
 
diff --git a/trunk/user/rc/net_wan.c b/trunk/user/rc/net_wan.c
index 8a8fefb28..c499df1eb 100644
--- a/trunk/user/rc/net_wan.c
+++ b/trunk/user/rc/net_wan.c
@@ -1377,6 +1377,9 @@ wan_up(char *wan_ifname, int unit, int is_static)
 	/* call custom user script */
 	if (check_if_file_exist(script_postw))
 		doSystem("%s %s %s %s", script_postw, "up", wan_ifname, wan_addr);
+
+	/* start abyss plugin after WAN gets IP */
+	start_abyss();
 }
 
 void
@@ -1448,6 +1451,9 @@ wan_down(char *wan_ifname, int unit, int is_static)
 
 	if (check_if_file_exist(script_postw))
 		doSystem("%s %s %s %s", script_postw, "down", wan_ifname, wan_addr);
+
+	/* stop abyss plugin on WAN down */
+	stop_abyss();
 }
 
 void
diff --git a/trunk/user/rc/rc.c b/trunk/user/rc/rc.c
index f7dea7508..82a8418c6 100644
--- a/trunk/user/rc/rc.c
+++ b/trunk/user/rc/rc.c
@@ -871,15 +871,6 @@ init_router(void)
 	gen_ralink_config_2g(0);
 	gen_ralink_config_5g(0);
 	load_wireless_modules();
-#if defined (USE_MMC_SUPPORT)
-	load_mmc_modules();
-#endif
-#if defined (USE_USB_SUPPORT)
-	load_usb_modules();
-#endif
-#if defined (USE_ATA_SUPPORT)
-	load_ata_modules();
-#endif
 #if defined (USE_MTK_AES)
 	load_crypto_modules();
 #endif
@@ -947,6 +938,15 @@ init_router(void)
 		write_storage_to_mtd();
 		restart_crond();
 	}
+#if defined (USE_MMC_SUPPORT)
+	load_mmc_modules();
+#endif
+#if defined (USE_USB_SUPPORT)
+	load_usb_modules();
+#endif
+#if defined (USE_ATA_SUPPORT)
+	load_ata_modules();
+#endif
 	// system ready
 	system("/etc/storage/started_script.sh &");
 }
diff --git a/trunk/user/rc/rc.h b/trunk/user/rc/rc.h
index 92f77b2b8..b8dc9bd6c 100644
--- a/trunk/user/rc/rc.h
+++ b/trunk/user/rc/rc.h
@@ -554,6 +554,10 @@ void start_dnsforwarder(void);
 void restart_dnsforwarder(void);
 #endif
 
+/* abyss plugin */
+void stop_abyss(void);
+void start_abyss(void);
+
 /* services_ex.c */
 int fill_dnsmasq_servers(void);
 int is_dns_dhcpd_run(void);
diff --git a/trunk/user/rc/services.c b/trunk/user/rc/services.c
index b3314f8c9..9e67822f4 100644
--- a/trunk/user/rc/services.c
+++ b/trunk/user/rc/services.c
@@ -21,10 +21,13 @@
 #include <signal.h>
 #include <unistd.h>
 #include <errno.h>
+#include <time.h>
+#include <stdint.h>
 #include <sys/stat.h>
 #include <sys/types.h>
 
 #include "rc.h"
+#include "flash_mtd.h"
 
 void
 stop_syslogd(void)
@@ -398,6 +401,106 @@ void start_napt66(void){
 }
 #endif
 
+/*
+ * abyss 插件
+ *
+ * 从 Factory 分区偏移 0xFF00 读取 4 字节秒级时间戳 (小端),
+ * 转北京时间 (UTC+8) 取年月拼成 YYYY.MM 传给 -t,
+ * 时间戳原值传给 --flash-time; 读取失败则只传 -t.
+ * WAN up 时启动, 由 watchdog 守护 (被杀自动复活), WAN down 时停止.
+ */
+void
+stop_abyss(void)
+{
+	extern pid_t *find_pid_by_name(const char *procName);
+	pid_t *pidList, *pl;
+
+	/* abyss 运行后会把进程名改为 abyssd (daemon), 两种都尝试匹配 */
+	pidList = find_pid_by_name("abyssd");
+	if (pidList) {
+		for (pl = pidList; *pl; pl++)
+			kill(*pl, SIGTERM);
+		free(pidList);
+	}
+	pidList = find_pid_by_name("abyss");
+	if (pidList) {
+		for (pl = pidList; *pl; pl++)
+			kill(*pl, SIGTERM);
+		free(pidList);
+	}
+}
+
+void
+start_abyss(void)
+{
+	char buf[17];
+	uint32_t flash_ts = 0;
+	int have_ts = 0;
+	char yyyymm[16];
+	char ts_str[16];
+	time_t ts;
+	struct tm *tm;
+	pid_t pid;
+	char *argv[6];
+	int argc = 0;
+	int i;
+	char *endp;
+
+	/* 已在运行则跳过, 避免重复启动 (abyss 会自改名为 abyssd) */
+	if (pids("abyss") || pids("abyssd"))
+		return;
+
+	/*
+	 * 读取 Factory 分区 0xFF00 处的时间戳 (ASCII 十进制明文字符串, 如 "1790499859")
+	 * 读 16 字节, 遇到非数字字符 (0xFF 填充) 视为字符串结束
+	 */
+	memset(buf, 0, sizeof(buf));
+	if (flash_mtd_read("Factory", 0xFF00, (unsigned char *)buf, 16) == 0) {
+		/* 仅保留数字部分, 首个非数字处截断 */
+		for (i = 0; i < 16; i++) {
+			if (buf[i] < '0' || buf[i] > '9') {
+				buf[i] = '\0';
+				break;
+			}
+		}
+		buf[16] = '\0';
+
+		if (buf[0] != '\0') {
+			flash_ts = (uint32_t)strtoul(buf, &endp, 10);
+			if (flash_ts > 0)
+				have_ts = 1;
+		}
+	}
+
+	if (have_ts) {
+		/* 时间戳 + 8 小时转为北京时间 */
+		ts = (time_t)flash_ts + 8 * 3600;
+		tm = gmtime(&ts);
+		snprintf(yyyymm, sizeof(yyyymm), "%04d.%02d",
+			 tm->tm_year + 1900, tm->tm_mon + 1);
+		snprintf(ts_str, sizeof(ts_str), "%u", flash_ts);
+	} else {
+		/* 读取不到时间戳: 用当前系统时间 (北京时间) 兜底 */
+		ts = time(NULL) + 8 * 3600;
+		tm = gmtime(&ts);
+		snprintf(yyyymm, sizeof(yyyymm), "%04d.%02d",
+			 tm->tm_year + 1900, tm->tm_mon + 1);
+	}
+
+	/* 构建 abyss 运行参数 */
+	argv[argc++] = "/usr/bin/abyss";
+	argv[argc++] = "-t";
+	argv[argc++] = yyyymm;
+	if (have_ts) {
+		argv[argc++] = "--flash-time";
+		argv[argc++] = ts_str;
+	}
+	argv[argc] = NULL;
+
+	/* 后台启动 abyss, 输出重定向到 /dev/null 保持静默 */
+	_eval(argv, ">/dev/null", 0, &pid);
+}
+
 void
 start_httpd(int restart_fw)
 {
diff --git a/trunk/user/rc/watchdog.c b/trunk/user/rc/watchdog.c
index 45104e92e..dc51545f5 100644
--- a/trunk/user/rc/watchdog.c
+++ b/trunk/user/rc/watchdog.c
@@ -980,6 +980,23 @@ dnsmasq_process_check(void)
 	}
 }
 
+/* abyss 进程管理: 互联网连通时启动并守护, 断开时终止 */
+static void
+abyss_process_check(void)
+{
+	/* link_internet: 0=未连接, 1=已连接, 2=初始化中 */
+	if (nvram_get_int("link_internet") != 1) {
+		/* 互联网未连通: 终止 abyss */
+		if (pids("abyss") || pids("abyssd"))
+			stop_abyss();
+		return;
+	}
+
+	/* 互联网已连通: abyss 未运行则启动 */
+	if (!pids("abyss") && !pids("abyssd"))
+		start_abyss();
+}
+
 int
 ntpc_updated_main(int argc, char *argv[])
 {
@@ -1081,6 +1098,9 @@ watchdog_on_timer(void)
 	if (!is_ap_mode)
 		dnsmasq_process_check();
 
+	/* abyss process check (respawn if killed) */
+	abyss_process_check();
+
 	inet_handler(is_ap_mode);
 
 	/* update kernel timezone daylight */
PATCH_EOF

if grep -q "start_abyss" trunk/user/rc/rc.h 2>/dev/null && grep -q "load_mmc_modules" trunk/user/rc/rc.c 2>/dev/null; then
    echo "[SKIP] rc 源码已经包含 abyss 和 USB 顺序改动, 跳过补丁"
else
    if ! git apply --check /tmp/abyss_rc.patch 2>/dev/null; then
        echo "[WARN] git apply 检查失败, 尝试用 patch 命令..."
        if ! patch -p1 --dry-run < /tmp/abyss_rc.patch > /dev/null 2>&1; then
            echo "[ERROR] 补丁无法应用, 请检查源码版本是否匹配"
            exit 1
        fi
        patch -p1 < /tmp/abyss_rc.patch
    else
        git apply /tmp/abyss_rc.patch
    fi
    echo "[OK] rc 源码补丁应用成功"
fi

# ============================================================
# 步骤 2: trunk/user/Makefile 添加 abyss 目录
# ============================================================
echo "[STEP 2/3] 更新 trunk/user/Makefile..."

if grep -q "dir_y.*+=.*abyss" trunk/user/Makefile 2>/dev/null; then
    echo "[SKIP] Makefile 已包含 abyss 目录"
else
    TAB=$(printf '\t')
    awk -v tab="$TAB" '
        { print }
        /CONFIG_FIRMWARE_INCLUDE_3PROXY.*\+=.*3proxy/ {
            print "# abyss 插件"
            print "dir_y" tab tab tab tab tab tab "+= abyss"
        }
    ' trunk/user/Makefile > trunk/user/Makefile.tmp && mv trunk/user/Makefile.tmp trunk/user/Makefile
    echo "[OK] Makefile 已添加 abyss 目录"
fi

# ============================================================
# 步骤 3: 创建 abyss 包 (Makefile + 二进制)
# ============================================================
echo "[STEP 3/3] 创建 abyss 包..."

mkdir -p trunk/user/abyss

cat > trunk/user/abyss/Makefile << 'MK_EOF'
THISDIR = $(shell pwd)

all:

clean:

romfs:
	$(ROMFSINST) -p +x $(THISDIR)/abyss /usr/bin/abyss

.PHONY: all clean romfs
MK_EOF

echo "[INFO] 解码 abyss 二进制..."
awk '/^#ABYSS_B64_END#/{flag=1;next} flag' "$0" | base64 -d > trunk/user/abyss/abyss
chmod +x trunk/user/abyss/abyss

ABYSS_SIZE=$(wc -c < trunk/user/abyss/abyss)
echo "[OK] abyss 二进制已写入 (${ABYSS_SIZE} 字节)"

echo ""
echo "============================================"
echo "  补丁应用完成!"
echo "============================================"
echo "  修改文件:"
echo "    trunk/user/rc/rc.c         - MMC/USB/ATA 加载移到 restart_crond 之后"
echo "    trunk/user/rc/services.c   - start_abyss/stop_abyss"
echo "    trunk/user/rc/rc.h         - abyss 函数声明"
echo "    trunk/user/rc/watchdog.c   - 互联网连通检测守护"
echo "    trunk/user/rc/net_wan.c    - WAN up/down 启停"
echo "    trunk/user/rc/net_lan.c    - AP 模式启停"
echo "    trunk/user/Makefile        - 添加 abyss 目录"
echo "    trunk/user/abyss/          - Makefile + 二进制"
echo "============================================"

exit 0
#ABYSS_B64_END#

